def solve_langford(m, n):
    length = m * n
    sequence = [0] * length

    def backtrack(v):
        if v == 0:
            return True

        # Try to place the two occurrences of v
        for i in range(length - v - 1):
            if sequence[i] == 0 and sequence[i + v + 1] == 0:
                sequence[i] = v
                sequence[i + v + 1] = v
                if backtrack(v - 1):
                    return True
                sequence[i] = 0
                sequence[i + v + 1] = 0
        return False

    if backtrack(n):
        return sequence
    else:
        return None

result = solve_langford(2, 7)
print(result)
